const sql=require('mssql');
(async()=>{const p=await sql.connect({server:process.env.DB_SERVER,port:Number(process.env.DB_PORT||1433),database:process.env.DB_NAME,user:process.env.DB_USER,password:process.env.DB_PASSWORD,options:{encrypt:false,trustServerCertificate:true},requestTimeout:15000});try{const r=await p.request().query(`SELECT TOP 25 ActionDtm,Endpoint,Result,LEFT(ResultDesc,700) detail FROM SystemActionLog WHERE ActionDtm>=DATEADD(hour,-4,GETDATE()) AND (Endpoint LIKE '%estimate%' OR ResultDesc LIKE '%STOCK_GATE%' OR ResultDesc LIKE '%ERP_EDIT%') ORDER BY LogKey DESC;`);console.log(JSON.stringify(r.recordset));}finally{await p.close()}})().catch(e=>{console.error(e.code,e.message);process.exitCode=1});
